  (SELECT jsonb_object_agg(key, value) FROM app_config WHERE scope = 'seller')  AS seller,
  (SELECT jsonb_object_agg(key, value) FROM app_config WHERE scope = 'etsy_rc') AS etsy_rc;

parameters.jsCode:
// Abrechnungsmonat bestimmen und Konfiguration prüfen.
// Schedule (1. des Monats): Vormonat. Webhook: {"month": "2026-09"} zum
// Nachholen oder erneuten Versenden; ohne Angabe ebenfalls der Vormonat.
const yearMonth = (d) => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit',
}).format(d);                                   // "2026-10"
const currentMonth = yearMonth(new Date());

let month = null;
if ($('Webhook: Monat manuell').isExecuted) {
  const req = $('Webhook: Monat manuell').first().json;
  month = req.body?.month ?? req.query?.month ?? null;
}
if (!month) {
  const [y, m] = currentMonth.split('-').map(Number);
  month = m === 1 ? `${y - 1}-12` : `${y}-${String(m - 1).padStart(2, '0')}`;
}
month = String(month).trim();
if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
  throw new Error(`Ungültiger Monat '${month}' – erwartet wird YYYY-MM`);
}
if (month >= currentMonth) {
  throw new Error(`${month} ist noch nicht abgeschlossen – abgerechnet werden nur vergangene Monate`);
}

// Ein veraltetes typst-api-Image ignoriert reverse_charge und würde still
// eine normale §19-Rechnung an Etsy erzeugen → vor dem Anlegen abbrechen.
const api = $('typst-api prüfen').first().json;
if (!(api.features ?? []).includes('reverse_charge')) {
  throw new Error('typst-api kennt keine Reverse-Charge-Rechnungen – Image neu bauen: '
    + 'docker compose up -d --build typst-api');
}

const cfg    = $('Konfiguration laden').first().json;
const seller = cfg.seller ?? {};
const rc     = cfg.etsy_rc ?? {};
// USt-IdNr. beider Seiten ist bei Reverse Charge Pflicht (§14a Abs. 1 UStG)
const missing = [
  ...['name', 'street', 'zip', 'city', 'vat_id']
      .filter(k => !seller[k]).map(k => `seller.${k}`),
  ...['recipient_name', 'recipient_street', 'recipient_city', 'recipient_country',
      'recipient_vat_id', 'start_date']
      .filter(k => !rc[k]).map(k => `etsy_rc.${k}`),
];
if (missing.length) {
  throw new Error(`Fehlende Konfiguration in app_config: ${missing.join(', ')} (siehe README)`);
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(rc.start_date)) {
  throw new Error(`etsy_rc.start_date '${rc.start_date}' – erwartet wird YYYY-MM-DD`);
}

const pick = (o, keys) => Object.fromEntries(keys.map(k => [k, o[k] ?? null]));
return [{
  json: {
    month,
    period:     `${month}-01`,
    start_date: rc.start_date,
    // Snapshots: werden mit der Rechnung gespeichert und beim Nachdruck verwendet
    seller: {
      ...pick(seller, ['name', 'business_name', 'tagline', 'street', 'zip', 'city', 'country',
                       'email', 'phone', 'website', 'iban', 'bank_name', 'tax_id', 'vat_id']),
      kleinunternehmer: String(seller.kleinunternehmer ?? 'true').toLowerCase() !== 'false',
    },
    recipient: {
      name:    rc.recipient_name,
      street:  rc.recipient_street,
      zip:     rc.recipient_zip ?? null,
      city:    rc.recipient_city,
      country: rc.recipient_country,
      vat_id:  rc.recipient_vat_id,
    },
    payment_note: rc.payment_note
      ?? 'Verrechnet über das Etsy-Zahlungskonto (Etsy Payments).',
    note: rc.note
      ?? 'Digitale Artikel (elektronisch erbrachte Leistungen), über die Etsy-Plattform an '
       + 'Endkunden verkauft. Etsy gilt dabei als leistender Unternehmer gegenüber dem '
       + 'Endkunden (Art. 9a MwSt-DVO); abgerechnet wird der Verkaufspreis ohne die von '
       + 'Etsy erhobene VAT.',
  },
}];

// Rechnung aus dem gespeicherten Snapshot aufbauen – ein Nachdruck ergibt
// exakt dieselbe Rechnung, auch wenn sich Bestellungen oder Stammdaten
// inzwischen geändert haben.
const r = $input.first().json;
const asObj = (v) => typeof v === 'string' ? JSON.parse(v) : v;
const lines = asObj(r.lines_json);
const eur = (n) => Number(n).toLocaleString('de-DE', { style: 'currency', currency: 'EUR' });
const de  = (iso) => String(iso).slice(0, 10).split('-').reverse().join('.');  // 2026-09-05 → 05.09.2026

const items = lines.map((l, i) => ({
  pos:         i + 1,
  description: `${l.titles} – Etsy-Bestellung ${l.order_id} vom ${de(l.date)}`,
  quantity:    1,
  unit_price:  Number(l.net),
  total:       Number(l.net),
}));

const net = Number(r.net_total);
const servicePeriod = `${r.service_from_de} – ${r.service_to_de}`;
const month = $('Monat & Konfiguration prüfen').first().json.month;

const mailText = [
  `Reverse-Charge-Rechnung an ${asObj(r.recipient_json).name} über die digitalen Verkäufe`
    + (r.is_new ? '.' : ' (bereits angelegt, erneut versendet).'),
  '',
  `Rechnungsnummer:    ${r.invoice_number}`,
  `Rechnungsdatum:     ${r.invoice_date_de}`,
  `Leistungszeitraum:  ${servicePeriod}`,
  `Verkäufe:           ${r.order_count}`,
  `Rechnungsbetrag:    ${eur(net)} (netto, ohne USt – Reverse Charge)`,
  '',
  'Abgleich mit dem Etsy-Zahlungskonto:',
  `  von Käufern gezahlt inkl. VAT:  ${eur(r.gross_total)}`,
  `  davon von Etsy erhobene VAT:    ${eur(r.marketplace_tax)}`,
  '',
  'Positionen:',
  ...lines.map(l => `  ${de(l.date)}  ${l.order_id}  ${eur(l.net).padStart(12)}  ${l.titles}`),
].join('\n');

return {
  json: {
    invoice_request: {
      invoice_number: r.invoice_number,
      invoice_date:   r.invoice_date_de,
      seller:         asObj(r.seller_json),
      buyer:          asObj(r.recipient_json),
      items,
      subtotal:       net,
      shipping_cost:  0,
      total:          net,
      currency:       r.currency,
      payment_note:   r.payment_note,
      note:           r.note,
      reverse_charge: true,
      service_period: servicePeriod,
    },
    mail_subject: `Reverse-Charge-Rechnung ${r.invoice_number} an Etsy – ${month}, ${eur(net)}`
      + (r.is_new ? '' : ' (erneut versendet)'),
    mail_text: mailText,
    result: {
      status:         r.is_new ? 'created' : 'existing',
      month,
      invoice_number: r.invoice_number,
      order_count:    r.order_count,
      net_total:      net,
    },
  },
};

// Keine (noch nicht abgerechneten) digitalen Verkäufe → keine Rechnung,
// keine Nummer verbraucht.
const month = $('Monat & Konfiguration prüfen').first().json.month;
return [{ json: { status: 'no_sales', month, message: `Keine abzurechnenden digitalen Verkäufe bis einschließlich ${month}` } }];
